    --navy-mid: #2b3558;
    --bg:       #f4f6f9;
    --white:    #ffffff;
    --border:   #dde3ec;
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'DM Sans', sans-serif;
    font-size: 14px;
    color: var(--navy);
    background: var(--bg);
    line-height: 1.65;
    padding: 40px 32px 80px;
  }

  .wrap { max-width: 860px; margin: 0 auto; }

  /* ── SECTION HEADER ── */
  .section-header {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 24px;
  }
  .section-num {
    width: 36px; height: 36px;
    border-radius: 50%;
    background: var(--navy);
    color: var(--white);
    font-size: 13px;
    font-weight: 600;
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
  }
  .section-title {
    font-family: 'DM Serif Display', serif;
    font-size: 22px;
    font-weight: 400;
    color: var(--navy);
  }

  /* ── INFO BOX ── */
  .info-box {
    background: var(--white);
    border: 1px solid var(--border);
    border-left: 4px solid var(--green);
    border-radius: 0 12px 12px 0;
    padding: 22px 26px;
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .info-box h3 {
    font-size: 13.5px;
    font-weight: 600;
    color: var(--navy);
  }

  .info-box p {
    font-size: 13px;
    color: #444;
    line-height: 1.75;
  }

  /* ── PRODUCTOS GRID ── */
  .productos {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
  }

  .prod-card {
    background: var(--green-lt);
    border: 1px solid #a8e8c6;
    border-radius: 10px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 5px;
  }

  .prod-session {
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #0f6e56;
  }

  .prod-title {
    font-size: 12.5px;
    font-weight: 600;
    color: var(--navy);
    line-height: 1.4;
  }

  .prod-tools {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    margin-top: 2px;
  }

  .badge-tool {
    font-size: 10.5px;
    font-weight: 500;
    color: var(--navy-mid);
    background: #fff;
    border: 1px solid var(--border);
    padding: 2px 8px;
    border-radius: 6px;
    white-space: nowrap;
  }

  /* ── WARN NOTE ── */
  .note {
    background: #fffbea;
    border-left: 4px solid #f5c842;
    border-radius: 0 10px 10px 0;
    padding: 12px 16px;
    font-size: 12.5px;
    color: #4a3800;
    line-height: 1.65;
  }

  .note strong { color: #7a5c00; }

  @media (max-width: 560px) {
    .productos { grid-template-columns: 1fr; }
  }
</style>
<div class="wrap">
<div class="section-header">
<div class="section-num">3</div>
<h2 class="section-title">Instrumento 3 · Rúbrica</h2>
</div>
<div class="info-box">
<h3>¿Qué evalúa y en qué momento?</h3>
<p>La rúbrica evalúa los tres productos finales de la SdA. Se aplica en las sesiones 6, 11 y 12, y se entrega al alumnado al inicio del proyecto para que actúe también como guía de calidad durante el proceso.</p>
<div class="productos">
<div class="prod-card"><span class="prod-session">Sesión 6</span>
<div class="prod-title">Configuración hardware grupal</div>
<div class="prod-tools"><span class="badge-tool">Google Docs</span> <span class="badge-tool">Canva</span></div>
</div>
<div class="prod-card"><span class="prod-session">Sesión 11</span>
<div class="prod-title">Configuración software grupal</div>
<div class="prod-tools"><span class="badge-tool">Google Docs</span></div>
</div>
<div class="prod-card"><span class="prod-session">Sesión 12</span>
<div class="prod-title">Presentación oral</div>
<div class="prod-tools"><span class="badge-tool">Genially</span></div>
</div>
</div>
<div class="note"><strong>Importante:</strong> la rúbrica se entrega al alumnado en la sesión 1 para que funcione como guía de calidad a lo largo de todo el proceso, no solo en el momento de la evaluación final.</div>
</div>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1778697197806-2a1zxstly","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<p><br /></p>
<style>
