  /* ── TOOL CARDS ── */
  .tool-card {
    background: var(--white);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 22px 24px;
    margin-bottom: 14px;
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .tool-header {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .tool-badge {
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #0f6e56;
    background: var(--green-lt);
    border: 1px solid #a8e8c6;
    padding: 3px 12px;
    border-radius: 20px;
    white-space: nowrap;
    flex-shrink: 0;
  }

  .tool-name {
    font-size: 14px;
    font-weight: 600;
    color: var(--navy);
  }

  .tool-body {
    font-size: 13px;
    color: #444;
    line-height: 1.75;
  }

  /* ── BULLET LIST ── */
  .tool-card ul {
    list-style: none;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 7px;
    margin-top: 2px;
  }

  .tool-card ul li {
    display: flex;
    gap: 10px;
    font-size: 13px;
    color: #444;
    line-height: 1.6;
  }

  .tool-card ul li::before {
